import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = sc.nextInt();
        }

        List<Integer> path = new ArrayList<>();
        List<List<Integer>> results = new ArrayList<>();
        subsets(nums, 0, path, results);
        for (List<Integer> subset : results) {
            System.out.println(subset);
        }
        System.out.println("Subsets: " + results.size());
    }

    static void subsets(int[] nums, int i, List<Integer> path, List<List<Integer>> results) {
        if (i == nums.length) {
            results.add(new ArrayList<>(path));
            return;
        }
        path.add(nums[i]);
        subsets(nums, i + 1, path, results);
        path.remove(path.size() - 1);
        subsets(nums, i + 1, path, results);
    }
}

