import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char[] letters = sc.next().toCharArray();
        Arrays.sort(letters);

        List<String> results = new ArrayList<>();
        permute(letters, new boolean[letters.length], new StringBuilder(), results);
        for (String word : results) {
            System.out.println(word);
        }
        System.out.println("Count: " + results.size());
    }

    static void permute(char[] letters, boolean[] used, StringBuilder sb, List<String> results) {
        if (sb.length() == letters.length) {
            results.add(sb.toString());
            return;
        }
        for (int i = 0; i < letters.length; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            sb.append(letters[i]);
            permute(letters, used, sb, results);
            sb.deleteCharAt(sb.length() - 1);
            used[i] = false;
        }
    }
}

