import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] tasks = new String[n];
        for (int i = 0; i < n; i++) {
            tasks[i] = sc.next();
        }
        Arrays.sort(tasks);

        List<String> results = new ArrayList<>();
        order(tasks, new boolean[n], new ArrayList<>(), results);
        for (String line : results) {
            System.out.println(line);
        }
        System.out.println("Orderings: " + results.size());
    }

    static void order(String[] tasks, boolean[] used, List<String> path, List<String> results) {
        if (path.size() == tasks.length) {
            results.add(String.join(" -> ", path));
            return;
        }
        for (int i = 0; i < tasks.length; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            path.add(tasks[i]);
            order(tasks, used, path, results);
            path.remove(path.size() - 1);
            used[i] = false;
        }
    }
}
